@page "/shipments"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Microsoft.AspNetCore.Authorization.Authorize(Roles = "Dispatcher")]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher – Shipments</PageTitle>

<h1>Shipments</h1>

<div class="row mb-3">
    <div class="col-md-4">
        <input class="form-control" placeholder="Search by tracking # or destination…"
               @bind="searchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter">
            <option value="">All Statuses</option>
            @foreach (var s in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@s">@s</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button class="btn btn-secondary w-100" @onclick="LoadShipments">Refresh</button>
    </div>
</div>

@if (shipments is null)
{
    <p><em>Loading shipments…</em></p>
}
else if (!FilteredShipments.Any())
{
    <p class="text-muted">No shipments match the current filter.</p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Customer</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Action</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><strong>@s.TrackingNumber</strong></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td>@s.CustomerEmail</td>
                        <td><span class="badge @StatusBadge(s.Status)">@s.Status</span></td>
                        <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</td>
                        <td>
                            @if (s.Status != ShipmentStatus.Delivered && s.Status != ShipmentStatus.Cancelled)
                            {
                                <select class="form-select form-select-sm" style="width:auto;display:inline-block"
                                        value="@s.Status"
                                        @onchange="e => UpdateStatus(s, e)">
                                    @foreach (var opt in Enum.GetValues<ShipmentStatus>())
                                    {
                                        <option value="@opt" selected="@(opt == s.Status)">@opt</option>
                                    }
                                </select>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<ShipmentDto>? shipments;
    private string searchTerm = "";
    private string statusFilter = "";

    private IEnumerable<ShipmentDto> FilteredShipments =>
        (shipments ?? []).Where(s =>
        {
            if (!string.IsNullOrWhiteSpace(statusFilter)
                && Enum.TryParse<ShipmentStatus>(statusFilter, out var f)
                && s.Status != f)
                return false;

            if (!string.IsNullOrWhiteSpace(searchTerm))
            {
                var term = searchTerm.Trim();
                return s.TrackingNumber.Contains(term, StringComparison.OrdinalIgnoreCase)
                    || s.Destination.Contains(term, StringComparison.OrdinalIgnoreCase);
            }
            return true;
        });

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            var updated = await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            var idx = shipments!.FindIndex(x => x.Id == shipment.Id);
            if (idx >= 0) shipments[idx] = updated;
        }
    }

    private static string StatusBadge(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@using Microsoft.AspNetCore.Components.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@inject IShipmentService ShipmentService
@inject AuthenticationStateProvider AuthStateProvider

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>

<div class="row mb-4">
    <div class="col-md-5">
        <div class="input-group">
            <input class="form-control" placeholder="Enter tracking number (e.g. SHP-10001)"
                   @bind="trackingNumber" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="SearchByTracking" disabled="@searching">
                @(searching ? "Searching…" : "Track")
            </button>
        </div>
    </div>
    <div class="col-md-3">
        <button class="btn btn-outline-secondary w-100" @onclick="LoadMyShipments">
            View My Shipments
        </button>
    </div>
</div>

@if (notFound)
{
    <div class="alert alert-warning">No shipment found with tracking number <strong>@lastSearched</strong>.</div>
}

@if (singleResult is not null)
{
    <div class="card mb-4">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>@singleResult.TrackingNumber</strong>
            <span class="badge @StatusBadge(singleResult.Status) fs-6">@singleResult.Status</span>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <p><strong>From:</strong> @singleResult.Origin</p>
                    <p><strong>To:</strong> @singleResult.Destination</p>
                    <p><strong>Description:</strong> @(singleResult.Description ?? "—")</p>
                </div>
                <div class="col-md-6">
                    <p><strong>Shipped:</strong> @singleResult.CreatedAt.ToString("MMM dd, yyyy")</p>
                    <p><strong>Estimated Delivery:</strong>
                        @(singleResult.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</p>
                    @if (singleResult.Status == ShipmentStatus.Delivered)
                    {
                        <div class="alert alert-success py-2 mb-0">✔ This shipment has been delivered.</div>
                    }
                    else if (singleResult.EstimatedDelivery.HasValue)
                    {
                        var daysLeft = (singleResult.EstimatedDelivery.Value.Date - DateTime.UtcNow.Date).Days;
                        <p class="text-muted">
                            @(daysLeft > 0 ? $"Arriving in ~{daysLeft} day(s)" :
                              daysLeft == 0 ? "Expected today" : "Delivery is past the estimate")
                        </p>
                    }
                </div>
            </div>
        </div>
    </div>
}

@if (myShipments is not null)
{
    <h4 class="mt-3">My Shipments</h4>
    @if (!myShipments.Any())
    {
        <p class="text-muted">No shipments are linked to your account.</p>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped">
                <thead>
                    <tr>
                        <th>Tracking #</th>
                        <th>Destination</th>
                        <th>Status</th>
                        <th>Est. Delivery</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var s in myShipments)
                    {
                        <tr @onclick="() => ShowDetail(s)" style="cursor:pointer">
                            <td>@s.TrackingNumber</td>
                            <td>@s.Destination</td>
                            <td><span class="badge @StatusBadge(s.Status)">@s.Status</span></td>
                            <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
}

@code {
    private string trackingNumber = "";
    private string lastSearched = "";
    private bool searching;
    private bool notFound;
    private ShipmentDto? singleResult;
    private List<ShipmentDto>? myShipments;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await SearchByTracking();
    }

    private async Task SearchByTracking()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        searching = true;
        notFound = false;
        singleResult = null;
        lastSearched = trackingNumber.Trim();

        singleResult = await ShipmentService.GetShipmentByTrackingNumberAsync(lastSearched);
        notFound = singleResult is null;
        searching = false;
    }

    private async Task LoadMyShipments()
    {
        var authState = await AuthStateProvider.GetAuthenticationStateAsync();
        var email = authState.User.FindFirst(System.Security.Claims.ClaimTypes.Email)?.Value
                 ?? authState.User.FindFirst("email")?.Value
                 ?? authState.User.Identity?.Name;
        if (email is not null)
        {
            myShipments = await ShipmentService.GetShipmentsByCustomerAsync(email);
        }
    }

    private void ShowDetail(ShipmentDto s)
    {
        singleResult = s;
        notFound = false;
    }

    private static string StatusBadge(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

